-- 回滚（mor_client_master）：撤销 20-client-master-ddl.sql 与 22 第 ① 步的 NOT NULL（83、84 之后执行，旧 client-master 镜像已换回）。
-- 删除三张新表（含发布后新代码写入的 t_party_role CLIENT 行、t_partner_role 维护记录，属不可逆部分）与收单资质列（运营修改过的档位丢失），
-- source_type 列 / 表注释恢复为执行前 mysqldump（2026-10-25T11:12Z）中的原文。
SET NAMES utf8mb4;
DROP TABLE IF EXISTS `t_client_partner_relation`;
DROP TABLE IF EXISTS `t_party_role`;
DROP TABLE IF EXISTS `t_partner_role`;
ALTER TABLE `t_operating_entity` DROP COLUMN `acquiring_qualification`;
ALTER TABLE `t_entity_source_relation`
  MODIFY COLUMN `source_type` varchar(64) NOT NULL COMMENT '该 Operating Entity 来源关系对应的来源主体类型。允许值：PLATFORM、CLIENT、PARTNER。',
  COMMENT='OE 的唯一来源认定关系；uk_source_effective(entity_no,effective_from)、uk_source_active(entity_no,active_source_slot)；source_type IN (PLATFORM,CLIENT,PARTNER)，Owner XOR；状态仅 ACTIVE/ENDED，仅 ACTIVE 的 active_source_slot=1；Client 来源依据仅为 SAME_PARTY/VERIFIED_ASSOCIATION；CHECK ((status=''ACTIVE'' AND active_source_slot=1) OR (status=''ENDED'' AND active_source_slot IS NULL))；CHECK (effective_to IS NULL OR effective_from < effective_to)；Owner XOR：PLATFORM 要求 source_client_id IS NULL AND source_partner_id IS NULL；CLIENT 要求 source_client_id IS NOT NULL AND source_partner_id IS NULL；PARTNER 要求 source_client_id IS NULL AND source_partner_id IS NOT NULL。；CLIENT 来源依据：SAME_PARTY 要求 Client Party=Operating Entity Party；VERIFIED_ASSOCIATION 要求两个 Party 不同，并由已批准申请、冻结材料和匹配的 Risk Qualification Decision 支撑；非 CLIENT 要求 client_source_basis IS NULL。；source_type、source_client_id、source_partner_id、client_source_basis 创建后不可修改；来源失效时只允许推进为 ENDED 并填写 effective_to。';
ALTER TABLE `t_operating_entity_application`
  MODIFY COLUMN `source_type` varchar(64) NOT NULL COMMENT '本次 Operating Entity 入驻申请的法律来源类型；PLATFORM 表示平台自有主体，提交 Actor 或入口渠道不由该字段表达。允许值：PLATFORM、CLIENT、PARTNER。',
  COMMENT='OE入驻或完整目标范围变更申请；uk_oe_app_no(application_no)、uk_oe_app_active(entity_no,active_slot)；申请状态/Slot 与 Client Application 相同；entity_no 非空稳定，ONBOARDING 使用 ENTITY_UNDERWRITING，SCOPE_CHANGE 使用 ENTITY_SCOPE_REVIEW（Risk 接入待后续实施）；仅 APPROVED 的 approved_source_relation_id 非空；application_type=ONBOARDING/SCOPE_CHANGE，Scope批准时核对base_entity_change_version；Risk新审核类型尚未接入时禁止自动激活范围；CHECK ((status IN (''DRAFT'',''SUBMITTED'',''UNDER_REVIEW'') AND active_slot=1) OR (status IN (''APPROVED'',''REJECTED'',''WITHDRAWN'') AND active_slot IS NULL))；CHECK ((qualification_decision_id IS NULL) = (qualification_decision_version IS NULL))；CHECK ((status=''APPROVED'' AND approved_source_relation_id IS NOT NULL) OR (status<>''APPROVED'' AND approved_source_relation_id IS NULL))；Risk Tuple 固定映射：role_type=OPERATING_ENTITY、role_id=entity_no、ONBOARDING 的 qualification_type=ENTITY_UNDERWRITING；SCOPE_CHANGE 的 qualification_type=ENTITY_SCOPE_REVIEW。；qualification_decision_id 与 qualification_decision_version 必须成组为空或成组非空。；APPROVED/REJECTED 前 due_diligence_case_id、qualification_decision_id、qualification_decision_version、qualification_type、role_type、role_id 必须匹配同一次 Risk 决策；WITHDRAWN 不要求 Decision。；qualification_type 由系统按申请类型固定为 ENTITY_UNDERWRITING 或 ENTITY_SCOPE_REVIEW，不接受调用方输入。；提交后 source_type、source_client_id、source_partner_id、client_source_basis 与 qualification_type 组成的 Source/Qualification Tuple 冻结且不可修改。；approved_source_relation_id 仅在 APPROVED 时非空，其他状态必须为空。；Source Owner XOR：PLATFORM 要求 source_client_id IS NULL AND source_partner_id IS NULL；CLIENT 要求 source_client_id IS NOT NULL AND source_partner_id IS NULL；PARTNER 要求 source_client_id IS NULL AND source_partner_id IS NOT NULL。；CLIENT 来源依据：SAME_PARTY 要求 Client Party=Operating Entity Party；VERIFIED_ASSOCIATION 要求两个 Party 不同，并由已批准申请、冻结材料和匹配的 Risk Qualification Decision 支撑；非 CLIENT 要求 client_source_basis IS NULL。；SCOPE_CHANGE 必须核对 base_entity_change_version 与完整目标 Scope，沿用既有主体和唯一来源关系，不回退主体状态；过时或拒绝的审核不能撤销现有范围。Risk 新 Tuple 未接入时禁止该流程激活范围。';
